{"cards": [{"node_code": "N_4e67d45016275d9d", "definition": "指对客运索道设计图纸、计算书、说明书等技术文件进行合规性审查、安全性评估及符合性鉴定的专业技术活动。", "boundary": "本节点聚焦于索道建设前的“纸面”技术审查。边界在于区分“设计文件鉴定”与“现场实体检验”：本节点针对设计阶段的文档与理论计算；制造过程中的实物检测归入“制造质量控制”；现场安装后的调试与验收归入“安装与改造”。若涉及设计变更，需区分是设计阶段的修改（本节点）还是施工阶段的调整（安装与改造）。", "includes": ["索道线路、支架、驱动装置等设计图纸的合规性审查", "索道结构强度、稳定性等关键参数的计算书复核", "设计说明书、安全规范符合性鉴定报告"], "excludes": ["索道制造过程中的零部件尺寸检测与材料化验（归入制造质量控制）", "索道安装现场的施工过程监督与竣工调试（归入安装与改造）"], "sibling_distinctions": [{"other_code": "N_1aa75e9b8d8c667f", "rule": "本节点审查“设计意图”与“理论方案”；兄弟节点控制“制造过程”与“实物质量”。"}, {"other_code": "N_84718d9039f0ff7b", "rule": "本节点关注设计文件的静态鉴定；兄弟节点关注现场安装的动态实施与改造施工。"}], "cross_boundary_rule": "若设计文件涉及通用机械原理，但服务于特定索道项目，主挂载本节点；若为纯理论力学研究且无具体索道应用背景，需视树中是否有机械工程节点，若无则保留在本节点作为技术基础。"}, {"node_code": "N_1aa75e9b8d8c667f", "definition": "指在客运索道关键部件及整机制造过程中，对原材料、加工工艺、装配质量及出厂性能进行监控与检验的技术管理活动。", "boundary": "本节点聚焦于索道“出厂前”的制造环节。边界在于区分“制造质量控制”与“设计鉴定”及“安装改造”：本节点针对工厂内的生产与质检；设计文件的理论审查归入“设计文件鉴定”；设备运抵现场后的安装、调试及后续改造归入“安装与改造”。若涉及通用制造工艺，需结合索道专用性判断。", "includes": ["索道钢丝绳、轮组、抱索器等关键部件的材料与加工检验", "索道整机装配过程的质量监控与出厂性能测试", "制造过程的质量记录、合格证及出厂检验报告"], "excludes": ["索道设计图纸的合规性审查与计算书复核（归入设计文件鉴定）", "索道现场安装施工、调试及后续技术改造（归入安装与改造）"], "sibling_distinctions": [{"other_code": "N_4e67d45016275d9d", "rule": "本节点控制“实物制造”质量；兄弟节点审查“设计文件”合规性。"}, {"other_code": "N_84718d9039f0ff7b", "rule": "本节点关注工厂内的“出厂前”质量控制；兄弟节点关注现场“安装后”的施工与改造。"}], "cross_boundary_rule": "涉及索道部件制造工艺时，若服务于具体索道制造项目，归入本节点；若为通用机械加工技术研究，需视树中是否有机械工程节点，若无则保留在本节点作为技术基础。"}, {"node_code": "N_84718d9039f0ff7b", "definition": "指客运索道设备在现场进行基础施工、设备安装、系统调试，以及既有索道进行技术升级、部件更换或线路改造的工程实施活动。", "boundary": "本节点聚焦于索道“落地”与“变更”的现场工程环节。边界在于区分“安装与改造”与“设计鉴定”及“制造控制”：本节点针对现场施工与调试；设计文件的理论审查归入“设计文件鉴定”；工厂内的制造质检归入“制造质量控制”。若涉及运行期间的日常维护与故障维修，归入“检验检测与维护”节点。", "includes": ["索道支架基础施工、设备吊装与现场组装", "索道系统联调联试、空载/负载运行测试及竣工验收", "既有索道的线路延长、速度提升、部件更换等改造施工"], "excludes": ["索道设计文件的合规性审查与计算书复核（归入设计文件鉴定）", "索道制造过程中的零部件检测与出厂检验（归入制造质量控制）", "索道运行期间的日常维护、定期检验与故障排除（归入检验检测与维护）"], "sibling_distinctions": [{"other_code": "N_4e67d45016275d9d", "rule": "本节点实施“现场安装”与“改造施工”；兄弟节点审查“设计文件”合规性。"}, {"other_code": "N_1aa75e9b8d8c667f", "rule": "本节点关注“现场”安装与改造；兄弟节点关注“工厂”制造质量控制。"}], "cross_boundary_rule": "涉及索道安装工艺或改造方案时，若服务于具体索道项目，归入本节点；若为通用起重设备安装技术研究，需视树中是否有机械工程节点，若无则保留在本节点作为技术基础。"}]}
